import json
import csv
import os
import base64

def task_func(raw_string, filename, output_dir):
    """
    Decode a base64-encoded JSON string, store the decoded data in a CSV file,
    and return the file path.
    """
    if not isinstance(filename, str) or not filename.strip():
        raise ValueError("filename must be a non-empty string")
    if not isinstance(output_dir, str) or not output_dir.strip():
        raise ValueError("output_dir must be a non-empty string")

    os.makedirs(output_dir, exist_ok=True)

    file_path = os.path.join(output_dir, filename)
    if not file_path.lower().endswith(".csv"):
        file_path += ".csv"

    if isinstance(raw_string, str):
        raw_bytes = raw_string.encode("utf-8")
    elif isinstance(raw_string, (bytes, bytearray)):
        raw_bytes = bytes(raw_string)
    else:
        raw_bytes = str(raw_string).encode("utf-8")

    try:
        decoded_bytes = base64.b64decode(raw_bytes, validate=True)
    except Exception:
        decoded_bytes = base64.b64decode(raw_bytes)

    decoded_text = decoded_bytes.decode("utf-8")
    data = json.loads(decoded_text)

    def serialize(value):
        if value is None or isinstance(value, (str, int, float, bool)):
            return value
        return json.dumps(value, ensure_ascii=False)

    with open(file_path, "w", newline="", encoding="utf-8") as csv_file:
        if isinstance(data, dict):
            fieldnames = list(data.keys())
            writer = csv.DictWriter(csv_file, fieldnames=fieldnames)
            writer.writeheader()
            writer.writerow({key: serialize(value) for key, value in data.items()})

        elif isinstance(data, list):
            if not data:
                pass
            elif all(isinstance(item, dict) for item in data):
                fieldnames = []
                seen = set()
                for item in data:
                    for key in item.keys():
                        if key not in seen:
                            seen.add(key)
                            fieldnames.append(key)

                writer = csv.DictWriter(csv_file, fieldnames=fieldnames)
                writer.writeheader()
                for item in data:
                    writer.writerow({key: serialize(item.get(key)) for key in fieldnames})
            else:
                writer = csv.writer(csv_file)
                writer.writerow(["value"])
                for item in data:
                    writer.writerow([serialize(item)])
        else:
            writer = csv.writer(csv_file)
            writer.writerow(["value"])
            writer.writerow([serialize(data)])

    return os.path.abspath(file_path)
